'use strict';
let language;
try { language = localStorage.getItem('tj-language') === 'ko' ? 'ko' : 'en'; } catch { language = 'en'; }
let activeProject = null, activeNode = 0, previousProjectId;
let activeView='home', lastWorkHash='#work';
const tr = value => typeof value === 'object' && value !== null && 'en' in value ? value[language] : value;
const esc = text => String(text ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const say = (en,ko) => esc(language === 'en' ? en : ko);
const txt = value => esc(tr(value));
const arrow = '<span class="arrow" aria-hidden="true">↗</span>';
const main = document.getElementById('main');
const resumeUrl = new URL('resume.html', document.currentScript.src).href;
const resumePdfUrl = new URL('assets/Taekjun_Lee_Resume.pdf', document.currentScript.src).href;
function renderChrome(project=null){
 document.documentElement.lang = language;
 const onJourney=location.hash.startsWith('#journey'),onWork=location.hash.startsWith('#work')||!!project;
 const navItems=`<a href="#work" ${onWork?'aria-current="page"':''}>${say('Work','프로젝트')}</a><a href="#journey" ${onJourney?'aria-current="page"':''}>${say('My journey','성장 여정')}</a><a href="#about">${say('About','소개')}</a><a class="resume-nav" href="${esc(resumePdfUrl)}" target="_blank" rel="noopener">${say('Résumé','이력서')} ${arrow}</a><a href="#contact">${say('Contact','연락처')}</a>`;
 document.getElementById('header').innerHTML=`<nav class="nav container" aria-label="${say('Main navigation','주요 메뉴')}"><a class="brand" href="#" aria-label="${say('TJ Lee, home','TJ Lee, 홈')}"><span class="monogram">tj<i>.</i></span><span class="brand-name">TAEKJUN LEE</span></a><div class="nav-controls"><div class="desktop-navigation">${navItems}</div><details class="mobile-navigation"><summary>${say('Explore','둘러보기')} <span aria-hidden="true">☰</span></summary><div class="mobile-nav-panel">${navItems}</div></details><button class="language" aria-label="${say('Switch to Korean','영어로 전환')}">${language==='en'?'EN / <span class="muted">KO</span>':'<span class="muted">EN</span> / KO'}</button></div></nav>`;
 document.getElementById('footer').innerHTML = `<div class="container footer-inner"><span>© ${new Date().getFullYear()} Taekjun (TJ) Lee · ${say('Built with purpose.','목적이 분명한 시스템을 만듭니다.')}</span><a href="#">${project||onJourney?say('Back to overview','전체 소개로'):say('Back to top','처음으로')} ↑</a></div>`;
 document.querySelector('.language').addEventListener('click',switchLanguage);
}
function switchLanguage(){
 const savedScroll=window.scrollY,savedNode=activeNode,openNotes=Array.from(document.querySelectorAll('.technical-note')).map(n=>n.open);
 language=language==='en'?'ko':'en';try{localStorage.setItem('tj-language',language);}catch{}
 render(true);
 if(activeProject){selectNode(savedNode);document.querySelectorAll('.technical-note').forEach((note,index)=>note.open=!!openNotes[index]);}
 if(activeView==='journey'&&location.hash.startsWith('#journey/'))scrollJourneyStage();else window.scrollTo({top:savedScroll,behavior:'instant'});
 document.querySelector('.language').focus({preventScroll:true});
}
function heroArt(){return `<svg viewBox="0 0 500 470" role="img" aria-label="${say('From field operations through shared data to connected applications','현장 업무에서 공통 데이터를 거쳐 연결된 애플리케이션으로')}"><defs><pattern id="hero-dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#c4cbb9"/></pattern><marker id="ha" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#9ba88c"/></marker></defs><rect x="4" y="25" width="492" height="408" rx="20" fill="url(#hero-dots)"/><g fill="none" stroke="#b6c0a8" stroke-width="1.3" marker-end="url(#ha)"><path d="M140 142H218V193"/><path d="M250 242V285H353V317"/><path d="M282 210H400V165"/><path d="M95 183V350H281"/></g><path d="M250 242V285H353V317" class="flow-edge active"/><g transform="translate(36 85)"><rect width="145" height="99" rx="10" fill="#fff" stroke="#c9d1bf"/><g transform="translate(16 17)" stroke="#67775a" fill="none" stroke-width="1.5"><path d="M0 20V7l13 7V7l13 7V0h8v20H0z"/><path d="M5 16v4m8-4v4m8-4v4"/></g><text x="16" y="62" font-size="13" fill="#283125" font-family="Arial">${say('Field operations','현장 업무')}</text><text x="16" y="81" font-size="9" fill="#7a856f" font-family="monospace">DOMAIN KNOWLEDGE</text></g><g transform="translate(180 192)"><rect width="145" height="98" rx="10" fill="#def68a" stroke="#9db866"/><g transform="translate(16 15)" stroke="#536634" fill="none" stroke-width="1.5"><ellipse cx="13" cy="4" rx="13" ry="4"/><path d="M0 4v18c0 6 26 6 26 0V4M0 12c0 6 26 6 26 0"/></g><text x="16" y="62" font-size="13" fill="#283125" font-family="Arial">${say('Reliable data','신뢰할 수 있는 데이터')}</text><text x="16" y="81" font-size="9" fill="#657845" font-family="monospace">SHARED FOUNDATION</text></g><g transform="translate(335 70)"><rect width="143" height="95" rx="10" fill="#fff" stroke="#c9d1bf"/><g transform="translate(16 16)" stroke="#67775a" fill="none" stroke-width="1.5"><rect width="29" height="22" rx="3"/><path d="M0 6h29M7 12h5m4 0h5M7 17h13"/></g><text x="16" y="60" font-size="13" fill="#283125" font-family="Arial">${say('Connected systems','연결된 시스템')}</text><text x="16" y="79" font-size="9" fill="#7a856f" font-family="monospace">WEB + INTEGRATIONS</text></g><g transform="translate(280 318)"><rect width="185" height="86" rx="10" fill="#283125"/><circle cx="23" cy="24" r="5" fill="#def68a"/><text x="38" y="28" font-size="10" fill="#c8d5b5" font-family="monospace">${say('LESS MANUAL WORK','반복 업무 감소')}</text><text x="18" y="60" font-size="16" fill="#fff" font-family="Arial">${say('Better ways to work.','더 나은 업무 방식.')}</text></g><circle cx="400" cy="210" r="4" fill="#ed6444"/><text x="38" y="244" font-size="9" fill="#7a856f" font-family="monospace">UNDERSTAND.</text><text x="38" y="261" font-size="9" fill="#7a856f" font-family="monospace">CONNECT.</text><text x="38" y="278" font-size="9" fill="#7a856f" font-family="monospace">AUTOMATE.</text></svg>`;}
function miniArt(id){
 const labels=id==='delivery' ? [say('Contractor','업체 제출'),say('Extract','데이터 추출'),say('Validate','자동 검수'),say('Approve','최종 승인')] : id==='master-data' ? [say('Master data','기준정보'),say('Quality','품질'),say('Maintenance','보전'),say('Operations','운영')] : [say('3D models','3D 모델'),say('Asset ID','설비 식별자'),say('Operations','운영 정보'),say('One workspace','통합 업무 공간')];
 const base=`<defs><marker id="mini-${id}" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#8b9b79"/></marker></defs>`;
 const box=(x,y,w,label,sub,accent=false)=>`<g><rect x="${x}" y="${y}" width="${w}" height="55" rx="7" fill="${accent?'#def68a':'#fff'}" stroke="${accent?'#a1b871':'#bfcbb2'}"/><text x="${x+w/2}" y="${y+24}" font-family="Arial,sans-serif" font-size="12" fill="#2d3728" text-anchor="middle">${label}</text><text x="${x+w/2}" y="${y+41}" font-family="monospace" font-size="8" fill="#7a876d" text-anchor="middle">${sub}</text></g>`;
 let graphic='';
 if(id==='delivery')graphic=`<g fill="none" stroke="#9daa8d" stroke-width="1.3" marker-end="url(#mini-${id})"><path d="M143 76H220"/><path d="M277 105V165"/><path d="M220 192H143"/><path d="M85 165V105" stroke-dasharray="4 4"/></g>${box(28,50,115,labels[0],'PORTAL')}${box(220,50,115,labels[1],'APS + LAMBDA')}${box(220,165,115,labels[2],'RULES + RDS')}${box(28,165,115,labels[3],'ENGINEER',true)}<text x="173" y="140" font-family="monospace" font-size="8" fill="#7a876d" text-anchor="middle">EVENT-DRIVEN</text>`;
 else if(id==='master-data')graphic=`<g fill="none" stroke="#9daa8d" stroke-width="1.3" marker-end="url(#mini-${id})"><path d="M144 134H181V43H217"/><path d="M144 134H217"/><path d="M144 134H181V223H217"/></g>${box(26,106,118,labels[0],'VALIDATE + SHARE',true)}${box(217,16,118,labels[1],'QUALITY')}${box(217,106,118,labels[2],'MAINTENANCE')}${box(217,196,118,labels[3],'OPERATIONS')}`;
 else graphic=`<g fill="none" stroke="#9daa8d" stroke-width="1.3" marker-end="url(#mini-${id})"><path d="M145 55H215"/><path d="M145 200H178V145H215"/><path d="M274 83V117"/></g>${box(28,28,117,labels[0],'MODELS')}${box(215,28,117,labels[1],'MAPPING')}${box(28,173,117,labels[2],'QUALITY + HISTORY')}${box(215,117,117,labels[3],'VUE + PYTHON',true)}<g transform="translate(246 200)" stroke="#8c9b78" fill="none"><path d="M0 0l20-11 20 11v24L20 35 0 24zM20 11v24M0 0l20 11L40 0"/></g>`;
 return `<svg viewBox="0 0 365 270" role="img" aria-label="${txt(projects.find(p=>p.id===id).flowTitle)}">${base}${graphic}</svg>`;
}
function workFilterKey(){const match=location.hash.match(/^#work\/([a-z]+)$/);return match&&workFilters[match[1]]?match[1]:'featured';}
function filterNavigation(){return `<nav class="work-filters" aria-label="${say('Explore work by role','직무 유형별 프로젝트 조회')}">${Object.entries(workFilters).map(([key,filter])=>`<a data-work-filter="${key}" href="${key==='featured'?'#work':'#work/'+key}">${txt(filter.label)}</a>`).join('')}</nav><div class="work-filter-context"><p id="filter-description"></p><span id="work-result-status" role="status" aria-live="polite"></span></div><div id="work-results" class="selected-grid"></div>`;}
function renderWorkGrid(){
 const result=document.getElementById('work-results');if(!result)return;
 const key=workFilterKey(),filter=workFilters[key];
 if(location.hash.startsWith('#work'))lastWorkHash=location.hash;
 document.querySelectorAll('[data-work-filter]').forEach(link=>{if(link.dataset.workFilter===key)link.setAttribute('aria-current','true');else link.removeAttribute('aria-current');});
 document.getElementById('filter-description').textContent=tr(filter.description);
 document.getElementById('work-result-status').textContent=language==='en'?`${filter.ids.length} ${key==='featured'?'featured cases':'experiences'}`:`${filter.ids.length}개 ${key==='featured'?'대표 사례':'경험'}`;
 result.className=`selected-grid ${key==='featured'?'':'filtered-grid'}`;
 result.innerHTML=filter.ids.map((id,index)=>card(projects.find(p=>p.id===id),index,key)).join('');
 const more=document.querySelector('.more-work');if(more)more.hidden=key!=='featured';
}
function journeyTeaser(){const stages=[journeyStages[0],journeyStages[1],journeyStages[4],journeyStages[5]];return `<section class="journey-section journey-teaser" id="journey-preview"><div class="container"><div class="journey-teaser-head"><div><div class="eyebrow">02 / ${say('HOW MY RESPONSIBILITIES GREW','담당 범위가 넓어진 과정')}</div><h2>${say('The systems evolved.','시스템의 발전과 함께,')}<br>${say('So did my role.','담당 범위도 넓어졌습니다.')}</h2></div><div><p class="journey-intro">${say('Field experience led to data and process design, then full-stack delivery and automation. Each project addressed a gap the earlier work helped reveal.','현장 경험에서 데이터·업무 설계로, 다시 풀스택 구현과 자동화로 역할을 확장했습니다. 앞선 경험에서 드러난 문제를 다음 과제로 연결했습니다.')}</p><a class="journey-link" href="#journey">${say('Follow the connected journey','과제와 성장의 연결 보기')} ${arrow}</a></div></div><div class="growth-path">${stages.map((stage,i)=>`<a href="#journey/${stage.id}"><span class="eyebrow">0${i+1}</span><strong>${txt(stage.stage)}</strong><span>${txt(stage.growth)}</span>${arrow}</a>`).join('')}</div></div></section>`;}
function renderJourney(){
 activeProject=null;activeView='journey';document.body.classList.remove('project-page');document.title=language==='en'?'My engineering journey — TJ Lee':'성장 여정 — TJ Lee';
 main.innerHTML=`<article class="journey-page page-enter"><div class="container"><div class="case-topbar"><a class="back-link" href="${lastWorkHash}">← ${say('Explore selected work','프로젝트 살펴보기')}</a><span class="eyebrow">${say('FIELD → DATA → SOFTWARE → AUTOMATION','현장 → 데이터 → 소프트웨어 → 자동화')}</span></div><section class="journey-hero"><div class="eyebrow orange">${say('ONE CONNECTED ENGINEERING JOURNEY','하나로 이어지는 엔지니어링 여정')}</div><h1>${say('From the field','현장의 문제에서')}<br>${say('to connected systems.','연결된 시스템까지.')}</h1><p>${say('I began by maintaining equipment and investigating operational data. My responsibilities expanded into data and process design, then the development, deployment and operation of connected applications.','설비를 유지보수하고 운영 데이터를 분석하는 일에서 시작했습니다. 이후 데이터·업무 설계, 연결된 애플리케이션의 개발·배포·운영으로 담당 범위를 넓혀왔습니다.')}</p></section><div class="journey-reading-note"><strong>${say('How to read this journey','이 여정을 읽는 방법')}</strong><p>${say('The sequence follows how the problems and technical foundations connect. Project dates overlap: data governance, application delivery and later extensions also progressed in parallel.','문제와 기술적 기반이 연결된 순서로 구성했습니다. 데이터 거버넌스·서비스 개발·후속 확장 등은 일부 병행했으며, 실제 수행 기간은 각 사례에 표시했습니다.')}</p></div></div><nav class="journey-index" aria-label="${say('Journey stages','성장 여정 단계')}"><div class="container">${journeyStages.map((stage,i)=>`<a href="#journey/${stage.id}" data-journey-stage="${stage.id}"><span>0${i+1}</span> ${txt(projects.find(p=>p.id===stage.id).navLabel)}</a>`).join('')}</div></nav><div class="container journey-timeline">${journeyStages.map((stage,i)=>{const p=projects.find(p=>p.id===stage.id);return `<section class="journey-chapter" id="journey-${stage.id}" aria-labelledby="journey-title-${stage.id}"><div class="chapter-meta"><span class="chapter-number">0${i+1}</span><span class="eyebrow">${esc(p.period)}</span><h2 id="journey-title-${stage.id}">${txt(stage.stage)}</h2><a class="text-link" href="#project/${stage.id}">${txt(p.short)} ${arrow}</a></div><div class="chapter-content"><div class="chapter-lanes"><div><h3>${say('THE NEXT PROBLEM','다음으로 해결할 문제')}</h3><p>${txt(stage.problem)}</p></div><div><h3>${say('MY EXPANDING RESPONSIBILITY','넓어진 담당 범위')}</h3><p>${txt(stage.role)}</p></div></div><div class="chapter-result"><span>${stage.id==='master-data'?say('MEASURED RESULT','측정 성과'):['digital-twin','data-platform'].includes(stage.id)?say('DELIVERY SCOPE','적용 범위'):say('DELIVERED CHANGE','업무 변화')}</span><p>${txt(p.cardProof)}</p></div><div class="chapter-growth"><span>${say('ROLE DEVELOPMENT','역할의 확장')}</span><strong>${txt(stage.growth)}</strong></div><div class="chapter-bridge"><span aria-hidden="true">${i===journeyStages.length-1?'↗':'↓'}</span><p>${txt(stage.enabled)}</p></div></div></section>`;}).join('')}<aside class="parallel-work"><div><span class="eyebrow">${say('ALONGSIDE PRODUCT DELIVERY','서비스 개발과 함께')}</span><h2>${say('Shared engineering practices','팀이 함께 사용하는 개발 기준')}</h2><p>${say('Reusable API, design, testability and fallback guidance grew alongside these systems. Agent work extends existing workflows and data integrations using external models.','이 시스템들을 개발하면서 API·디자인·테스트 가능성·fallback 기준도 팀에서 재사용하도록 정리했습니다. 에이전트 업무는 외부 모델을 활용해 기존 워크플로와 데이터 연계를 확장하는 방향입니다.')}</p></div><a class="text-link" href="#project/engineering-practices">${say('Explore engineering practices','개발 방식 살펴보기')} ${arrow}</a></aside><div class="journey-end"><h2>${say('Choose the work relevant to your role.','직무에 맞는 경험을 확인하세요.')}</h2><div class="actions"><a class="button" href="#work/development">${say('Software development','소프트웨어 개발')} ${arrow}</a><a class="button light" href="#work/automation">${say('Workflow automation','업무 자동화')} ${arrow}</a><a class="text-link" href="${esc(resumePdfUrl)}" target="_blank" rel="noopener">${say('Résumé (PDF)','이력서 (PDF)')} ${arrow}</a></div></div></div></article>`;
}
function caseConnections(p){
 const stage=journeyById[p.id];if(!stage)return `<aside class="case-connections parallel-connection"><div><span class="eyebrow">${say('PART OF THE WIDER JOURNEY','성장 여정과의 연결')}</span><p>${say('Shared engineering standards and workflow prototypes developed alongside production systems.','운영 시스템 개발과 함께 발전시킨 공통 개발 기준과 업무 프로토타입입니다.')}</p></div><a class="text-link" href="#journey">${say('See the full journey','전체 여정 보기')} ${arrow}</a></aside>`;
 const prior=journeyStages[stage.index-1],next=journeyStages[stage.index+1];
 return `<aside class="case-connections"><div class="connection-heading"><span class="eyebrow">${say('HOW THIS WORK CONNECTS','앞뒤 과제와의 연결')}</span><a href="#journey/${p.id}">${say('My journey','성장 여정')} ${arrow}</a></div><p class="connection-growth">${txt(stage.growth)}</p><div class="connection-grid"><div><span>${prior?say('FOUNDATION','출발 기반'):say('STARTING POINT','출발점')}</span>${prior?`<a href="#project/${prior.id}">${txt(projects.find(c=>c.id===prior.id).short)} ${arrow}</a>`:`<strong>${say('Hands-on facilities engineering','직접 경험한 설비 엔지니어링')}</strong>`}<p>${txt(prior?prior.enabled:stage.problem)}</p></div><div><span>${next?say('ENABLED THE NEXT STEP','이어진 확장'):say('EXPANDED THE SCOPE','넓어진 개선 범위')}</span>${next?`<a href="#project/${next.id}">${txt(projects.find(c=>c.id===next.id).short)} ${arrow}</a>`:`<strong>${say('Automation from the point of submission','데이터 제출 단계부터 자동화')}</strong>`}<p>${txt(stage.enabled)}</p></div></div></aside>`;
}

function card(p,index,filter='featured'){
 const featured=filter==='featured',focus=p.focus?.[filter],proof=p.cardProof;
 return `<a href="#project/${p.id}" class="project-card ${featured&&index===0?'featured':''} ${featured?'':'compact-card'}" aria-label="${say('Read case study: ','사례 보기: ')}${txt(p.short)}"><div class="card-content"><div class="card-meta"><span class="eyebrow">${txt(p.category)}</span><span class="project-number">${p.number} /</span></div><h3>${txt(p.short)}</h3>${featured?`<p class="card-hook">${txt(p.title)}</p>`:''}<p class="card-roles">${p.roles.slice(0,3).map(txt).join(' · ')}</p><p>${txt(focus||p.summary)}</p>${proof?`<div class="card-proof">${txt(proof)}</div>`:''}<div class="card-tags">${p.stack.slice(0,4).map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div><div class="card-link"><span>${say('View case study','사례 자세히 보기')}</span>${arrow}</div></div>${featured?`<div class="card-art"><span class="art-tag">${p.id==='master-data'?'SYSTEM ARCHITECTURE':'WORKFLOW OVERVIEW'}</span>${miniArt(p.id)}</div>`:''}</a>`;
}
function confidentiality(compact=false){return compact?`<p class="confidential-note">${say('Company code, internal screens and production data are confidential. Diagrams explain high-level workflows with sensitive details omitted.','회사 코드·내부 화면·운영 데이터는 보안상 공개하지 않습니다. 도식은 민감한 세부 정보를 제외한 상위 업무 흐름을 설명합니다.')}</p>`:`<details class="disclosure" id="disclosure"><summary>${say('About these case studies & confidentiality','사례 공개 범위 · 보안 안내')} <span aria-hidden="true">＋</span></summary><p>${say('My work supports semiconductor manufacturing infrastructure. To respect company confidentiality and industrial-technology protection requirements, I do not publish company source code, internal screenshots, production data or detailed infrastructure configurations. The case studies describe my responsibilities, high-level workflows and engineering decisions with sensitive details omitted. Internal materials are not available as public demos or interview attachments.','반도체 제조 인프라를 지원하는 업무 특성상 회사의 기밀·산업기술 보호 요구사항을 준수하기 위해 소스 코드·내부 화면·운영 데이터·상세 인프라 구성을 공개하지 않습니다. 본 사례는 민감한 세부 정보를 제외하고 담당 범위·상위 업무 흐름·설계 판단을 설명합니다. 회사 내부 자료는 공개 데모나 면접 첨부 자료로 제공하지 않습니다.')}</p></details>`;}
