function edgePath(from,to,kind){
 const dx=to[1]-from[1],dy=to[2]-from[2];
 if(kind==='loop' && dx===0) return `M${from[1]-80} ${from[2]}H${from[1]-110}V${to[2]}H${to[1]-80}`;
 if(Math.abs(dx)>Math.abs(dy)*.7){const direction=dx>0?1:-1;const sx=from[1]+80*direction,ex=to[1]-80*direction;const mid=(sx+ex)/2;return `M${sx} ${from[2]}H${mid}V${to[2]}H${ex}`;}
 const direction=dy>0?1:-1;const sy=from[2]+44*direction,ey=to[2]-44*direction;const mid=(sy+ey)/2;return `M${from[1]} ${sy}V${mid}H${to[1]}V${ey}`;
}
function workflow(p){
 const paths=p.edges.map(([a,b,kind])=>{const from=p.nodes.find(n=>n[0]===a),to=p.nodes.find(n=>n[0]===b);return `<path class="flow-edge ${kind?'dashed':''}" data-from="${a}" data-to="${b}" d="${edgePath(from,to,kind)}" marker-end="url(#flow-arrow)"/>`;}).join('');
 return `<section class="workflow" aria-labelledby="workflow-title"><div class="workflow-head"><div><div class="eyebrow">${say('SYSTEM WALKTHROUGH','시스템 워크플로')}</div><h2 id="workflow-title">${txt(p.flowTitle)}</h2></div><p class="workflow-hint">${txt(p.flowNote)} ${say('Click a node or use the arrows below.','박스를 누르거나 아래 화살표로 이동하세요.')}</p></div><label class="workflow-select"><span>${say('Explore a stage','단계 선택')}</span><select id="workflow-stage-select">${p.nodes.map((n,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} / ${txt(n[3])}</option>`).join('')}</select></label><div class="diagram-scroll" tabindex="0" role="region" aria-label="${say('Architecture diagram, scroll horizontally on small screens','아키텍처 다이어그램, 작은 화면에서는 가로로 스크롤할 수 있습니다')}"><div class="diagram"><svg class="diagram-lines" viewBox="0 0 1000 430" aria-hidden="true"><defs><marker id="flow-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#8c9d78" stroke-width="1.2"/></marker></defs>${paths}</svg>${p.nodes.map((n,i)=>`<button class="flow-node" style="left:${n[1]/10}%;top:${n[2]/4.3}%" data-node="${i}" aria-pressed="${i===0}" aria-controls="step-detail"><span class="node-num">${String(i+1).padStart(2,'0')} /</span><span class="node-title">${txt(n[3])}</span><span class="node-sub">${txt(n[4])}</span></button>`).join('')}</div></div><div class="workflow-detail" id="step-detail" aria-live="polite" aria-atomic="true"></div></section>`;
}
function selectNode(index,moveView=false){
 const p=activeProject;if(!p)return;activeNode=index;const n=p.nodes[index];const selector=document.getElementById('workflow-stage-select');if(selector)selector.value=String(index);
 document.querySelectorAll('.flow-node').forEach((node,i)=>node.setAttribute('aria-pressed',String(i===index)));
 document.querySelectorAll('.flow-edge[data-from]').forEach(edge=>edge.classList.toggle('active',edge.dataset.from===n[0]||edge.dataset.to===n[0]));
 document.getElementById('step-detail').innerHTML=`<div class="step-badge">${String(index+1).padStart(2,'0')}</div><div class="step-copy"><h3>${txt(n[3])}</h3><p>${txt(n[5])}</p></div><div class="step-controls"><button class="step-control" data-step="-1" aria-label="${say('Previous workflow stage','이전 단계')}" ${index===0?'disabled':''}>←</button><button class="step-control" data-step="1" aria-label="${say('Next workflow stage','다음 단계')}" ${index===p.nodes.length-1?'disabled':''}>→</button></div>`;
 document.querySelectorAll('[data-step]').forEach(button=>button.addEventListener('click',()=>{const direction=Number(button.dataset.step);selectNode(activeNode+direction,true);const next=document.querySelector(`[data-step="${direction}"]:not(:disabled)`);if(next)next.focus({preventScroll:true});else document.querySelector(direction>0?'[data-step="-1"]':'[data-step="1"]').focus({preventScroll:true});}));
 if(moveView){const scroller=document.querySelector('.diagram-scroll');const node=document.querySelector(`[data-node="${index}"]`);scroller.scrollTo({left:node.offsetLeft-scroller.clientWidth/2,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
}
function projectNav(p){return `<nav class="project-nav" aria-label="${say('Project navigation','프로젝트 이동')}"><div class="container project-nav-inner"><a class="project-nav-back" href="${lastWorkHash}">← ${say('Back to work','프로젝트로')}</a><div class="project-nav-links">${projects.map(c=>`<a href="#project/${c.id}" ${c.id===p.id?'aria-current="page"':''}>${txt(c.navLabel)}</a>`).join('')}</div><label class="project-switch"><span class="sr-only">${say('Choose a case study','프로젝트 선택')}</span><select id="project-switch">${projects.map(c=>`<option value="${c.id}" ${c.id===p.id?'selected':''}>${c.number} / ${txt(c.short)}</option>`).join('')}</select></label></div></nav>`;}
function implementationNotes(p){if(!p.details?.length)return '';return `<section class="implementation-notes" id="implementation"><div class="section-heading"><div><div class="eyebrow">${say('TECHNICAL DEPTH','기술 상세')}</div><h2>${say('Inside the implementation.','구현 과정의 판단과 운영.')}</h2></div><p>${say('Expand a topic for constraints, implementation and operational checks. Company-specific identifiers and configurations are omitted.','항목을 펼치면 제약·구현·운영 관점을 확인할 수 있습니다. 회사 고유 식별자와 상세 구성은 제외했습니다.')}</p></div>${p.details.map((d,i)=>`<details class="technical-note"><summary><span class="note-index">0${i+1}</span><span>${txt(d.title)}</span><span class="note-plus" aria-hidden="true">＋</span></summary><div class="note-body"><div><h3>${say('CONSTRAINT','제약')}</h3><p>${txt(d.challenge)}</p></div><div><h3>${say('IMPLEMENTATION','구현')}</h3><p>${txt(d.implementation)}</p></div><div><h3>${say('VERIFICATION & OPERATIONS','검증 · 운영 관점')}</h3><p>${txt(d.verification)}</p></div></div></details>`).join('')}</section>`;}
function metricKind(kind){const names={outcome:L('OUTCOME','성과'),scope:L('SCOPE','적용 규모'),method:L('APPROACH','방법'),capability:L('CAPABILITY','기능'),context:L('BACKGROUND','배경')};return txt(names[kind]||names.scope);}
function renderProject(p){
 activeProject=p;activeView='project';document.body.classList.add('project-page');document.title=`${tr(p.short)} — TJ Lee`;
 const next=projects[(projects.indexOf(p)+1)%projects.length];
 main.innerHTML=`${projectNav(p)}<article class="container page-enter"><div class="case-topbar"><span class="eyebrow">${txt(p.category)} · ${esc(p.period)}</span><span class="status-label"><span class="dot"></span>${txt(p.status)}</span></div><section class="case-hero"><h1>${txt(p.short)}</h1><p class="case-hook">${txt(p.title)}</p><p class="case-summary">${txt(p.summary)}</p><div class="case-role"><span class="eyebrow">${say('MY ROLE','담당 역할')}</span><span>${txt(p.role)}</span></div></section><div class="case-metrics">${p.metrics.map(([value,label],i)=>`<div class="case-metric"><span class="metric-kind">${metricKind(p.metricKinds?.[i])}</span><strong class="${value==='17% → 0%'?'metric-rate':''}">${txt(value)}</strong><span>${txt(label)}</span></div>`).join('')}</div>${p.measurement?`<p class="measure-note">${txt(p.measurement)}</p>`:''}${caseConnections(p)}<div class="case-jumps"><a href="#case-change">${say('What changed','업무 변화')} ↓</a><a href="#case-flow">${say('System workflow','시스템 흐름')} ↓</a>${p.details?.length?`<a href="#implementation">${say('Implementation notes','구현 상세')} ↓</a>`:''}</div><div class="change-grid" id="case-change"><div><div class="change-label">${say('BEFORE / THE FRICTION','BEFORE / 기존 문제')}</div><p>${txt(p.before)}</p></div><div><div class="change-label after">${say('AFTER / WHAT CHANGED','AFTER / 달라진 업무')}</div><p>${txt(p.after)}</p></div></div><div id="case-flow">${workflow(p)}</div>${confidentiality(true)}<section class="case-body"><div><div class="eyebrow">${say('THE OUTCOME','변화와 결과')}</div><h2>${say('What became possible.','무엇이 가능해졌는가.')}</h2><p class="case-outcome">${txt(p.outcome)}</p></div><div><div class="eyebrow contribution-title">${say('MY CONTRIBUTION','직접 담당한 부분')}</div><ul class="contributions">${p.contribution.map(c=>`<li>${txt(c)}</li>`).join('')}</ul></div></section>${p.owned?`<aside class="ownership scope-boundary"><h2>${say('Scope boundary · existing platforms & collaborators','담당 범위 구분 · 기반 기술과 협업')}</h2><p>${txt(p.foundation)}</p></aside>`:''}<section class="decision-grid" aria-label="${say('Engineering decisions','설계 판단')}">${p.decisions.map((d,i)=>`<div class="decision"><div class="eyebrow">${say('DESIGN DECISION','설계 판단')} 0${i+1}</div><h3>${txt(d)}</h3><p>${txt(p.decisionText[i])}</p></div>`).join('')}</section>${implementationNotes(p)}<div class="case-stack"><span class="eyebrow">${say('TOOLS & METHODS','기술 · 방법')}</span><div class="toolkit">${p.stack.map(s=>`<span>${esc(s)}</span>`).join('')}</div></div>${p.extension?`<aside class="extension"><span class="eyebrow">${say('EXTENDING THE FOUNDATION','기반 위의 확장')}</span>${txt(p.extension)}</aside>`:''}<div class="case-contact"><span>${say('Discussing a software or automation role?','소프트웨어·자동화 직무를 채용하고 계신가요?')}</span><a class="text-link" href="mailto:${profile.email}">${say('Contact TJ','TJ에게 연락하기')} ${arrow}</a><a class="text-link" href="${esc(resumePdfUrl)}" target="_blank" rel="noopener">${say('Résumé (PDF)','이력서 (PDF)')} ${arrow}</a></div><a class="next-case" href="#project/${next.id}"><div><div class="eyebrow">${say('CONTINUE EXPLORING','다른 사례 살펴보기')} / ${next.number}</div><h3>${txt(next.short)}</h3></div>${arrow}</a></article>`;
 document.getElementById('project-switch').addEventListener('change',event=>{location.hash=`project/${event.target.value}`;});
 document.getElementById('workflow-stage-select').addEventListener('change',event=>selectNode(Number(event.target.value),true));
 document.querySelectorAll('[data-node]').forEach(button=>button.addEventListener('click',()=>selectNode(Number(button.dataset.node))));selectNode(0);
}
function syncNavigation(){const hash=location.hash;document.querySelectorAll('.desktop-navigation a, .mobile-nav-panel a').forEach(link=>{const active=link.hash==='#work'?(hash.startsWith('#work')||hash.startsWith('#project/')):link.hash==='#journey'?hash.startsWith('#journey'):link.hash===hash&&hash!=='';if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});}
function scrollJourneyStage(shouldScroll=true){const match=location.hash.match(/^#journey\/([a-z-]+)$/);document.querySelectorAll('[data-journey-stage]').forEach(link=>{if(match&&link.dataset.journeyStage===match[1])link.setAttribute('aria-current','step');else link.removeAttribute('aria-current');});if(!shouldScroll)return;if(match){const target=document.getElementById('journey-'+match[1]);if(target){const route=location.hash;requestAnimationFrame(()=>target.scrollIntoView({behavior:'instant'}));document.fonts.ready.then(()=>{if(location.hash===route&&target.isConnected)target.scrollIntoView({behavior:'instant'});});}}else window.scrollTo({top:0,behavior:'instant'});}
function render(preservePosition=false){
 const hash=location.hash,match=hash.match(/^#project\/([a-z-]+)$/),project=match?projects.find(p=>p.id===match[1]):null;
 const currentScroll=window.scrollY;renderChrome(project);syncNavigation();
 if(project){renderProject(project);window.scrollTo({top:previousProjectId===project.id?currentScroll:0,behavior:'instant'});previousProjectId=project.id;}
 else if(hash==='#journey'||hash.startsWith('#journey/')){renderJourney();previousProjectId=null;scrollJourneyStage(!preservePosition);}
 else{renderHome();previousProjectId=null;const target=document.getElementById(hash.startsWith('#work')?'work':hash.slice(1));if(preservePosition)window.scrollTo({top:currentScroll,behavior:'instant'});else if(target)requestAnimationFrame(()=>target.scrollIntoView({behavior:'instant'}));else window.scrollTo({top:0,behavior:'instant'});}
}
window.addEventListener('hashchange',()=>{
 const hash=location.hash;syncNavigation();
 if(activeView==='home'&&!hash.startsWith('#project/')&&!hash.startsWith('#journey')){renderWorkGrid();const target=document.getElementById(hash.startsWith('#work')?'work':hash.slice(1));if(target)target.scrollIntoView({behavior:'instant'});else window.scrollTo({top:0,behavior:'instant'});return;}
 if(activeView==='journey'&&(hash==='#journey'||hash.startsWith('#journey/'))){scrollJourneyStage();return;}
 render();main.focus({preventScroll:true});
});
document.addEventListener('click',event=>{
 const mobileLink=event.target.closest('.mobile-nav-panel a');if(mobileLink){const menu=mobileLink.closest('details');menu.open=false;requestAnimationFrame(()=>main.focus({preventScroll:true}));}
 const link=event.target.closest('.case-jumps a, .skip');if(!link)return;const target=document.getElementById(link.hash.slice(1));if(target){event.preventDefault();if(target===main)main.focus({preventScroll:true});target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
});
render();
